// 年度独立存储 key，便于跨年重置
const CHECKIN_STORAGE_KEY = 'shopLevel-checkin-2026';

interface CheckinData {
  // key: step 标题（第一步/第二步...），value: true 表示已完成
  steps: Record<string, boolean>;
  // 最近一次打卡时间（ISO string）
  lastCheckinAt?: string;
}

function loadCheckin(): CheckinData {
  try {
    const raw = scopedStorage.getItem(CHECKIN_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as CheckinData;
      if (parsed && typeof parsed.steps === 'object') return parsed;
    }
  } catch (e) {
    logger.warn('加载店铺阶段打卡状态失败:', String(e));
  }
  return { steps: {} };
}

function saveCheckin(data: CheckinData) {
  try {
    scopedStorage.setItem(CHECKIN_STORAGE_KEY, JSON.stringify(data));
  } catch (e) {
    logger.warn('保存店铺阶段打卡状态失败:', String(e));
  }
}

function formatCheckinTime(iso?: string): string {
  if (!iso) return '暂无';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '暂无';
  const m = d.getMonth() + 1;
  const day = d.getDate();
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${m}月${day}日 ${hh}:${mm}`;
}

