import { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ChevronLeft, ChevronRight, TrendingUp, DollarSign, ShoppingCart, Target, Eye, CalendarCheck, ClipboardCheck } from 'lucide-react';
import CollapsibleSection from '@/components/CollapsibleSection';
import MonthlyDiagnosticPromptCard from '@/components/MonthlyDiagnosticPromptCard';
import MonthlyPatrolCard from './MonthlyPatrolCard';
import {
  type IKpiDailyRecord,
  calculateKpiMetrics,
  getKpiStatus,
  loadUserRecords,
  formatDate,
  getMonthRange,
} from '@/data/kpi';
import type { ThemeConfig } from '@/lib/theme';

interface MonthlyPlanSectionProps {
  theme: ThemeConfig;
}

function fmtMoney(v: number): string {
  return v.toFixed(2);
}
function fmtPercent(v: number): string {
  return (v * 100).toFixed(1);
}

export default function MonthlyPlanSection({ theme }: MonthlyPlanSectionProps) {
  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.getMonth()); // 0-11

  const records = useMemo<IKpiDailyRecord[]>(() => loadUserRecords('guest'), []);

  // 当前查看月的记录
  const monthRecords = useMemo(() => {
    const start = `${viewYear}-${String(viewMonth + 1).padStart(2, '0')}-01`;
    const lastDay = new Date(viewYear, viewMonth + 1, 0).getDate();
    const end = `${viewYear}-${String(viewMonth + 1).padStart(2, '0')}-${lastDay}`;
    return records.filter(r => r.date >= start && r.date <= end);
  }, [records, viewYear, viewMonth]);

  const monthMetrics = useMemo(() => calculateKpiMetrics(monthRecords), [monthRecords]);
  const monthOrderCount = useMemo(
    () => monthRecords.reduce((s, r) => s + r.orderCount, 0),
    [monthRecords],
  );
  const monthListingCount = useMemo(
    () => monthRecords.reduce((s, r) => s + r.listingCount, 0),
    [monthRecords],
  );
  const monthStatus = useMemo(
    () => getKpiStatus(monthMetrics, monthOrderCount),
    [monthMetrics, monthOrderCount],
  );

  // 每月业绩列表（按日期倒序）
  const sortedRecords = useMemo(
    () => [...monthRecords].sort((a, b) => b.date.localeCompare(a.date)),
    [monthRecords],
  );

  function prevMonth() {
    setViewMonth(prev => {
      if (prev === 0) {
        setViewYear(y => y - 1);
        return 11;
      }
      return prev - 1;
    });
  }
  function nextMonth() {
    setViewMonth(prev => {
      if (prev === 11) {
        setViewYear(y => y + 1);
        return 0;
      }
      return prev + 1;
    });
  }

  const isCurrentMonth = viewYear === now.getFullYear() && viewMonth === now.getMonth();

  const [expandedMap, setExpandedMap] = useState<Record<string, boolean>>({
    patrol: true,
    kpi: true,
    detail: true,
    diagnostic: false,
  });

  function toggleSection(key: string) {
    setExpandedMap(prev => ({ ...prev, [key]: !prev[key] }));
  }

  return (
    <div className="space-y-3">
      {/* 每月巡店打卡清单 */}
      <CollapsibleSection
        title="每月巡店打卡清单"
        subtitle="月度必查5项，提前规避风险"
        summary="销量、时效、风控、售后、跟卖"
        badge="5项"
        badgeColor="default"
        theme={theme}
        expanded={expandedMap.patrol}
        onToggle={() => toggleSection('patrol')}
        className="!shadow-none !border-0"
      >
        <MonthlyPatrolCard theme={theme} year={viewYear} month={viewMonth} />
      </CollapsibleSection>

      {/* 月份切换 */}
      <Card
        className="border-0"
        style={{
          backgroundColor: theme.ui.glassBg,
          backdropFilter: 'blur(12px) saturate(180%)',
          WebkitBackdropFilter: 'blur(12px) saturate(180%)',
          boxShadow: theme.ui.glassShadow,
          border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
        }}
      >
        <CardHeader className="pb-2">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <CalendarCheck className="size-5" style={{ color: theme.primary }} />
              <CardTitle className="text-base">每月巡店汇总</CardTitle>
            </div>
            <div className="flex items-center gap-1">
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={prevMonth}
                aria-label="上个月"
              >
                <ChevronLeft className="size-4" />
              </Button>
              <span className="text-sm font-medium min-w-[100px] text-center">
                {viewYear}年{viewMonth + 1}月
              </span>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={nextMonth}
                aria-label="下个月"
              >
                <ChevronRight className="size-4" />
              </Button>
            </div>
          </div>
          {isCurrentMonth && (
            <p className="text-xs text-muted-foreground mt-1">本月实时数据，每日录入后自动更新</p>
          )}
        </CardHeader>
      </Card>

      {/* KPI 卡片 */}
      <CollapsibleSection
        title="本月业绩概览"
        subtitle={`累计出单 ${monthOrderCount} 单 · 上架 ${monthListingCount} 个`}
        theme={theme}
        expanded={expandedMap.kpi}
        onToggle={() => toggleSection('kpi')}
      >
         <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3">
           <div
             className="p-4 rounded-lg border min-w-0"
             style={{ backgroundColor: theme.ui.glassBg, borderColor: theme.ui.cardBorder }}
           >
             <div className="flex items-center gap-2 mb-2">
               <ShoppingCart className="size-4 shrink-0" style={{ color: theme.primary }} />
               <span className="text-xs text-muted-foreground truncate">累计出单</span>
             </div>
             <div className="text-xl md:text-2xl font-bold tabular-nums truncate">{monthOrderCount}</div>
             <div className="text-xs text-muted-foreground mt-0.5 truncate">单</div>
           </div>

           <div
             className="p-4 rounded-lg border min-w-0"
             style={{ backgroundColor: theme.ui.glassBg, borderColor: theme.ui.cardBorder }}
           >
             <div className="flex items-center gap-2 mb-2">
               <DollarSign className="size-4 shrink-0" style={{ color: '#22c55e' }} />
               <span className="text-xs text-muted-foreground truncate">累计销售额</span>
             </div>
             <div className="text-xl md:text-2xl font-bold tabular-nums truncate">${fmtMoney(monthMetrics.totalSales)}</div>
             <div className="text-xs text-muted-foreground mt-0.5 truncate">
               ROI {monthMetrics.roi >= 0 ? '+' : ''}{(monthMetrics.roi * 100).toFixed(0)}%
             </div>
           </div>

           <div
             className="p-4 rounded-lg border min-w-0"
             style={{ backgroundColor: theme.ui.glassBg, borderColor: theme.ui.cardBorder }}
           >
             <div className="flex items-center gap-2 mb-2">
               <Target className="size-4 shrink-0" style={{ color: '#f97316' }} />
               <span className="text-xs text-muted-foreground truncate">月均 ACOS</span>
             </div>
             <div className="text-xl md:text-2xl font-bold tabular-nums truncate">{fmtPercent(monthMetrics.acos)}%</div>
             <div className="text-xs text-muted-foreground mt-0.5 truncate">
               广告花费 ${fmtMoney(monthMetrics.totalCost)}
             </div>
           </div>

           <div
             className="p-4 rounded-lg border min-w-0"
             style={{ backgroundColor: theme.ui.glassBg, borderColor: theme.ui.cardBorder }}
           >
             <div className="flex items-center gap-2 mb-2">
               <DollarSign className="size-4 shrink-0" style={{ color: '#8b5cf6' }} />
               <span className="text-xs text-muted-foreground truncate">月均 TACOS</span>
             </div>
             <div className="text-xl md:text-2xl font-bold tabular-nums truncate">{fmtPercent(monthMetrics.tacos)}%</div>
             <div className="text-xs text-muted-foreground mt-0.5 truncate">
               广告占总销售额
             </div>
           </div>

           <div
             className="p-4 rounded-lg border min-w-0"
             style={{ backgroundColor: theme.ui.glassBg, borderColor: theme.ui.cardBorder }}
           >
             <div className="flex items-center gap-2 mb-2">
               <TrendingUp className="size-4 shrink-0" style={{ color: '#10b981' }} />
               <span className="text-xs text-muted-foreground truncate">自然单占比</span>
             </div>
             <div className="text-xl md:text-2xl font-bold tabular-nums truncate">
               {fmtPercent(monthMetrics.naturalOrderRate)}%
             </div>
             <div className="text-xs text-muted-foreground mt-0.5 truncate">
               自然单 {monthRecords.reduce((s, r) => s + (r.naturalOrders || 0), 0)} 单
             </div>
           </div>

           <div
             className="p-4 rounded-lg border min-w-0"
             style={{ backgroundColor: theme.ui.glassBg, borderColor: theme.ui.cardBorder }}
           >
             <div className="flex items-center gap-2 mb-2">
               <Eye className="size-4 shrink-0" style={{ color: '#0ea5e9' }} />
               <span className="text-xs text-muted-foreground truncate">月均转化率</span>
             </div>
             <div className="text-xl md:text-2xl font-bold tabular-nums truncate">
               {fmtPercent(monthMetrics.conversionRate)}%
             </div>
             <div className="text-xs text-muted-foreground mt-0.5 truncate">
               总访问 {monthRecords.reduce((s, r) => s + r.totalVisits, 0).toLocaleString()}
             </div>
           </div>
          </div>
       </CollapsibleSection>

       {/* 业绩诊断提示词 */}
       <MonthlyDiagnosticPromptCard
         theme={theme}
         expanded={expandedMap.diagnostic}
         onToggle={() => toggleSection('diagnostic')}
       />

       {/* 每日业绩列表 */}
      <CollapsibleSection
        title="每日业绩明细"
        subtitle={`本月共 ${sortedRecords.length} 天有记录`}
        theme={theme}
        expanded={expandedMap.detail}
        onToggle={() => toggleSection('detail')}
      >
        <Card
          className="border"
          style={{
            backgroundColor: theme.ui.glassBg,
            borderColor: theme.ui.cardBorder,
          }}
        >
          <CardContent className="pt-4 p-0">
            {sortedRecords.length === 0 ? (
              <div className="py-12 text-center text-muted-foreground">
                <TrendingUp className="size-8 mx-auto mb-2 opacity-30" />
                <p className="text-sm">本月暂无业绩记录</p>
                <p className="text-xs text-muted-foreground mt-1">
                  前往「KPI 驾驶舱」录入每日数据
                </p>
              </div>
            ) : (
              <div className="w-full overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                     <tr className="border-b" style={{ borderColor: theme.ui.cardBorder }}>
                       <th className="px-3 py-2.5 text-left font-medium text-muted-foreground whitespace-nowrap">日期</th>
                       <th className="px-3 py-2.5 text-right font-medium text-muted-foreground whitespace-nowrap">出单</th>
                       <th className="px-3 py-2.5 text-right font-medium text-muted-foreground whitespace-nowrap">总销售额</th>
                       <th className="px-3 py-2.5 text-right font-medium text-muted-foreground whitespace-nowrap">ACOS</th>
                       <th className="px-3 py-2.5 text-right font-medium text-muted-foreground whitespace-nowrap">TACOS</th>
                       <th className="px-3 py-2.5 text-right font-medium text-muted-foreground whitespace-nowrap">转化率</th>
                       <th className="px-3 py-2.5 text-right font-medium text-muted-foreground whitespace-nowrap">退款率</th>
                       <th className="px-3 py-2.5 text-left font-medium text-muted-foreground whitespace-nowrap min-w-[200px]">备忘</th>
                     </tr>
                  </thead>
                  <tbody>
                    {sortedRecords.map(record => {
                      const m = calculateKpiMetrics([record]);
                      return (
                        <tr
                          key={record.id}
                          className="border-b"
                          style={{ borderColor: theme.ui.cardBorder }}
                        >
                          <td className="px-3 py-2.5 whitespace-nowrap font-medium">
                            {record.date}
                          </td>
                          <td className="px-3 py-2.5 text-right tabular-nums font-medium">
                            {record.orderCount}
                          </td>
                           <td className="px-3 py-2.5 text-right tabular-nums">
                             <span className="text-muted-foreground mr-1">{record.currency || 'USD'}</span>
                             {fmtMoney(m.totalSales)}
                           </td>
                           <td className="px-3 py-2.5 text-right tabular-nums">
                             <span style={{ color: getKpiStatus(m, record.orderCount).acos.color }}>
                               {fmtPercent(m.acos)}%
                             </span>
                           </td>
                           <td className="px-3 py-2.5 text-right tabular-nums">
                             <span style={{ color: m.tacos > 0.4 ? '#dc2626' : m.tacos > 0.25 ? '#f59e0b' : '#16a34a' }}>
                               {fmtPercent(m.tacos)}%
                             </span>
                           </td>
                           <td className="px-3 py-2.5 text-right tabular-nums">
                             <span style={{ color: getKpiStatus(m, record.orderCount).conversion.color }}>
                               {fmtPercent(m.conversionRate)}%
                             </span>
                           </td>
                           <td className="px-3 py-2.5 text-right tabular-nums">
                             <span style={{ color: getKpiStatus(m, record.orderCount).refund.color }}>
                               {fmtPercent(m.refundRate)}%
                             </span>
                           </td>
                           <td className="px-3 py-2.5 text-left text-xs text-muted-foreground">
                             <span className="block truncate max-w-[260px]" title={record.note}>
                               {record.note || '—'}
                             </span>
                           </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      </CollapsibleSection>
    </div>
  );
}
