export default function MonthlyDiagnosticPromptCard({ theme, expanded, onToggle }: MonthlyDiagnosticPromptCardProps) {
  const [copied, setCopied] = useState(false);
  const copyTimerRef = useRef<number | null>(null);

  // 清理复制状态定时器，避免卸载后 setState
  useEffect(() => {
    return () => {
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current);
        copyTimerRef.current = null;
      }
    };
  }, []);

  async function handleCopy(e: React.MouseEvent) {
    e.stopPropagation();
    try {
      await copyToClipboard(FULL_PROMPT_TEXT);
      setCopied(true);
      toast.success('已复制到剪贴板');
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = window.setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('复制失败，请手动选择复制');
    }
  }

  return (
    <CollapsibleSection
      title="业绩诊断提示词 · 月度复盘"
      subtitle="坂田五虎、华南城四少、龙华十三狼等龙头公司级别操盘手视角 · 月度业绩深度诊断"
      summary="一键复制，粘贴到AI对话框直接使用"
      icon={<ListTodo className="size-5" />}
      badge="月度诊断"
      badgeColor="warning"
      theme={theme}
      expanded={expanded}
      onToggle={onToggle}
      className="!shadow-none !border-0"
      headerExtra={
        <Button
          size="sm"
          variant="secondary"
          onClick={handleCopy}
          className="h-7 text-xs gap-1"
        >
          {copied ? (
            <>
              <Check className="size-3.5" />
              已复制
            </>
          ) : (
            <>
              <Copy className="size-3.5" />
              一键复制
            </>
          )}
        </Button>
      }
    >
      <div className="rounded-lg border border-border/50 bg-card/30 p-3 sm:p-4 max-h-[650px] overflow-y-auto">
        <PromptContent />
      </div>
      <div className="mt-3 flex items-center justify-between text-xs text-muted-foreground">
        <span>共 {FULL_PROMPT_TEXT.length} 字 · 六大模块结构化提示词</span>
        <Badge variant="outline" className="text-[10px] font-normal">
          月度复盘
        </Badge>
      </div>
    </CollapsibleSection>
  );
}
