import { lazy, Suspense, useState } from 'react';
import { useOutletContext } from 'react-router-dom';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { CalendarDays, BarChart3, CalendarCheck } from 'lucide-react';
import DailyPlanContent from './DailyPlanContent';
import MonthlyPlanSection from './MonthlyPlanSection';
import type { ThemeConfig, FestivalBadge } from '@/lib/theme';

const KpiDashboardSection = lazy(() => import('./KpiDashboardSection'));

export default function DailyPlanPage() {
  const { theme, festival, themeOverride, setThemeOverride, isLoggedIn, user, syncStatus } =
    useOutletContext<{
      theme: ThemeConfig;
      festival: FestivalBadge;
      themeOverride: string;
      setThemeOverride: (v: string) => void;
      isLoggedIn: boolean;
      user: { username?: string; nickname?: string } | null;
      syncStatus: string;
    }>();
  const [activeTab, setActiveTab] = useState<'daily' | 'monthly' | 'kpi'>('daily');

  return (
    <div className="space-y-3">
      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as typeof activeTab)}>
        <TabsList className="grid grid-cols-3 w-full">
          <TabsTrigger value="daily" className="gap-1.5">
            <CalendarDays className="size-4" />
            每日巡店
          </TabsTrigger>
          <TabsTrigger value="monthly" className="gap-1.5">
            <CalendarCheck className="size-4" />
            每月巡店
          </TabsTrigger>
          <TabsTrigger value="kpi" className="gap-1.5">
            <BarChart3 className="size-4" />
            KPI 驾驶舱
          </TabsTrigger>
        </TabsList>

        <TabsContent value="daily" className="mt-3">
          <DailyPlanContent
            theme={theme}
            festival={festival}
            themeOverride={themeOverride}
            setThemeOverride={setThemeOverride}
          />
        </TabsContent>

        <TabsContent value="monthly" className="mt-3">
          <MonthlyPlanSection theme={theme} />
        </TabsContent>

        <TabsContent value="kpi" className="mt-3">
          <Suspense fallback={<KpiSkeleton />}>
            <KpiDashboardSection theme={theme} />
          </Suspense>
        </TabsContent>
      </Tabs>
    </div>
  );
}

function KpiSkeleton() {
  return (
    <div className="space-y-3 animate-pulse">
      <div className="h-6 bg-muted rounded w-1/3" />
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {[0, 1, 2, 3].map((i) => (
          <div key={i} className="h-24 bg-muted rounded-lg" />
        ))}
      </div>
      <div className="h-[320px] bg-muted rounded-lg" />
    </div>
  );
}
