import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import {
  ClipboardCheck,
  ShoppingCart,
  Truck,
  Shield,
  Megaphone,
  Mail,
  Tag,
  CheckCircle2,
  RotateCcw,
  Receipt,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import type { ThemeConfig } from '@/lib/theme';

interface MonthlyPatrolProps {
  theme: ThemeConfig;
  year: number;
  month: number; // 0-11
}

interface MonthlyPatrolItem {
  key: string;
  title: string;
  subtitle: string | string[];
  icon: typeof ShoppingCart;
  color: string;
}

// 每月巡店标准清单 - 6项
const MONTHLY_PATROL_ITEMS: MonthlyPatrolItem[] = [
  {
    key: 'sales',
    title: '销量检查',
    subtitle: [
      '跟上月对比订单出单节奏是否稳定',
      '检查库存产品是否被跟卖，如有影响销量一定安排处理',
    ],
    icon: ShoppingCart,
    color: '#3b82f6',
  },
  {
    key: 'logistics',
    title: '时效追踪',
    subtitle: [
      '盘点所有在途货件状态，防止因物流延误导致售后问题',
      '如是旺季，外地仓的渠道要做好物色新货代备选，避免渠道涨价和渠道时效导致货物运输成本上涨和运输时效拖沓！',
    ],
    icon: Truck,
    color: '#f97316',
  },
  {
    key: 'risk',
    title: '风控排查',
    subtitle: '是否有保持订单排查风控避免TRO，深度搜索后台和邮箱所有历史邮件，确保没有遗漏任何疑似侵权、律所取证或TRO警告的隐藏邮件',
    icon: Shield,
    color: '#ef4444',
  },
  {
    key: 'ad',
    title: '广告排查',
    subtitle: [
      '是否查看广告数据和预算，对比上月是否做到控制预算',
      '是否有定期进行否定词和否定产品',
    ],
    icon: Megaphone,
    color: '#f59e0b',
  },
  {
    key: 'aftersale',
    title: '售后排查',
    subtitle: [
      '检查是否有因疏忽导致的遗漏未回复邮件/退款申请，确保绩效安全',
      '是否一单多款的产品有事先询问数量，避免误买，多买等不必要的售后争端',
    ],
    icon: Mail,
    color: '#8b5cf6',
  },
  {
    key: 'tax',
    title: '税务提醒',
    subtitle: '是否每月15号前有做好申报处理，避免执照异常！如是首月要联系代办询问是否开通税务！如当月是6月要记得做年报！',
    icon: Receipt,
    color: '#14b8a6',
  },
];

const MONTHLY_PATROL_STORAGE_KEY = 'patrol:monthly';
const MONTHLY_PATROL_VERSION = 6;

function getMonthKey(year: number, month: number): string {
  return `${year}-${String(month + 1).padStart(2, '0')}`;
}

function loadMonthlyPatrol(year: number, month: number): Record<string, boolean> {
  try {
    const monthKey = getMonthKey(year, month);
    const savedKey = scopedStorage.getItem(`${MONTHLY_PATROL_STORAGE_KEY}:date`);
    const savedData = scopedStorage.getItem(`${MONTHLY_PATROL_STORAGE_KEY}:data`);
    const savedVersion = scopedStorage.getItem(`${MONTHLY_PATROL_STORAGE_KEY}:version`);
    if (savedKey === monthKey && savedData && savedVersion === String(MONTHLY_PATROL_VERSION)) {
      return JSON.parse(savedData);
    }
  } catch (e) {
    logger.warn('加载每月巡店状态失败:', String(e));
  }
  return {};
}

function saveMonthlyPatrol(year: number, month: number, state: Record<string, boolean>) {
  try {
    const monthKey = getMonthKey(year, month);
    scopedStorage.setItem(`${MONTHLY_PATROL_STORAGE_KEY}:date`, monthKey);
    scopedStorage.setItem(`${MONTHLY_PATROL_STORAGE_KEY}:data`, JSON.stringify(state));
    scopedStorage.setItem(`${MONTHLY_PATROL_STORAGE_KEY}:version`, String(MONTHLY_PATROL_VERSION));
  } catch (e) {
    logger.warn('保存每月巡店状态失败:', String(e));
  }
}

export default function MonthlyPatrolCard({ theme, year, month }: MonthlyPatrolProps) {
  const [checked, setChecked] = useState<Record<string, boolean>>(() =>
    loadMonthlyPatrol(year, month),
  );

  // 月份切换时重新加载
  useEffect(() => {
    setChecked(loadMonthlyPatrol(year, month));
  }, [year, month]);

  // 自动保存
  useEffect(() => {
    saveMonthlyPatrol(year, month, checked);
  }, [year, month, checked]);

  const totalCount = MONTHLY_PATROL_ITEMS.length;
  const checkedCount = useMemo(
    () => Object.values(checked).filter(Boolean).length,
    [checked],
  );
  const progress = totalCount > 0 ? (checkedCount / totalCount) * 100 : 0;
  const allDone = checkedCount === totalCount;

  function toggleItem(key: string) {
    setChecked(prev => ({ ...prev, [key]: !prev[key] }));
  }

  function resetAll() {
    setChecked({});
  }

  return (
    <Card
      className="border-0 overflow-hidden"
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        boxShadow: theme.ui.glassShadow,
        border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
      }}
    >
      <CardHeader className="pb-2">
        <div className="flex items-start justify-between gap-3 flex-wrap">
          <div>
            <CardTitle className="text-base flex items-center gap-2">
              <ClipboardCheck className="size-5" style={{ color: theme.primary }} />
              每月巡店打卡清单
              <Badge
                className="text-xs font-normal ml-1 border-0"
                style={{ backgroundColor: theme.ui.badgeBg, color: theme.primary }}
              >
                {`月度必查${totalCount}项`}
              </Badge>
            </CardTitle>
            <CardDescription className="text-xs mt-1">
              每月盘点一次，提前规避风险，保障店铺稳健运营
            </CardDescription>
          </div>
          <div className="text-right shrink-0">
            <div className="text-sm text-muted-foreground">
              本月完成度
              <span className="text-base font-bold ml-1" style={{ color: theme.primary }}>
                {checkedCount}/{totalCount}
              </span>
            </div>
          </div>
        </div>
        <div className="h-1.5 w-full bg-primary/20 rounded-full mt-2 overflow-hidden">
          <div
            className="h-full rounded-full transition-all duration-500"
            style={{
              width: `${progress}%`,
              backgroundColor: allDone ? theme.priority.p0 : theme.primary,
            }}
          />
        </div>
        {allDone && (
          <div className="text-xs mt-2 flex items-center gap-1.5" style={{ color: theme.priority.p0 }}>
            <CheckCircle2 className="size-3.5" />
            本月巡店全部完成，继续保持 ✅
          </div>
        )}
      </CardHeader>
      <CardContent className="space-y-3 pt-0">
        <div className="flex gap-2 flex-wrap">
          <Button
            size="sm"
            variant="ghost"
            onClick={resetAll}
            className="text-xs h-8"
          >
            <RotateCcw className="size-3.5 mr-1" />
            重置本月清单
          </Button>
        </div>

        <div className="space-y-2">
          {MONTHLY_PATROL_ITEMS.map(item => {
            const Icon = item.icon;
            const isChecked = !!checked[item.key];
            return (
              <div
                key={item.key}
                className={`
                  flex items-start gap-3 p-3 rounded-lg border transition-all cursor-pointer
                  ${isChecked ? 'opacity-60' : 'hover:opacity-90'}
                `}
                style={{
                  backgroundColor: isChecked ? 'transparent' : theme.ui.glassBg,
                  borderColor: theme.ui.glassBorder || theme.ui.cardBorder,
                }}
                onClick={() => toggleItem(item.key)}
              >
                <Checkbox
                  checked={isChecked}
                  onCheckedChange={() => toggleItem(item.key)}
                  className="shrink-0 mt-0.5 data-[state=checked]:bg-primary data-[state=checked]:border-primary"
                  style={{
                    // @ts-expect-error css var 注入
                    '--checkbox-bg': theme.primary,
                  }}
                />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <Icon className="size-4 shrink-0" style={{ color: item.color }} />
                    <span
                      className={`text-sm font-medium ${isChecked ? 'line-through text-muted-foreground' : 'text-foreground'}`}
                    >
                      {item.title}
                    </span>
                  </div>
                  <p
                    className={`text-xs mt-1 leading-relaxed ${isChecked ? 'line-through text-muted-foreground' : 'text-muted-foreground'}`}
                  >
                    {Array.isArray(item.subtitle) ? (
                      <span className="flex flex-col gap-1">
                        {item.subtitle.map((line, idx) => (
                          <span key={idx}>· {line}</span>
                        ))}
                      </span>
                    ) : (
                      item.subtitle
                    )}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </CardContent>
    </Card>
  );
}
